def bo_machine(store, build_id, snapshot=None, revision=None):
    if snapshot is None:
        history = store.history()
        snapshot = history[-1]["snapshot"] if history else store.snapshot()
        revision = history[-1]["revision"] if history else 0
    builds = {r["run_id"]: r["build_id"] for r in snapshot.get("run_builds", [])}
    configurations = []
    for run in snapshot["runs"]:
        acts = [a for a in snapshot["activities"] if a["run_id"] == run["id"]]
        configuration = {
            "attempt": run["id"], "param_version": run["version"],
            "phase": run["state"], "state_revision": revision,
            "context": {**run, "printing": run["parameters"], "checks": acts},
            "activities": {"check-" + a["name"]: {"passed": "succeeded", "failed": "rejected", "error": "failed"}.get(a["state"], a["state"]) for a in acts},
            "check_results": acts, "journal": [],
            "run_build_id": builds.get(run["id"]),
            "source_status": "current" if builds.get(run["id"]) == build_id else "unknown_or_other_build",
        }
        configurations.append(bo_finite(configuration))
    return {"configurations": configurations,
            "current": configurations[-1]["phase"] if configurations else None,
            "journal": [], "state_revision": revision,
            "shared_resources": {"printer." + p["id"]: {**bo_finite(p), "capacity": 1, "available": 0 if p["occupant"] else 1, "holder": p["occupant"]} for p in snapshot["printers"]},
            "project_constraints": {"scope": "global SQLite occupancy plus parallel checks", "errors": validate_instances(snapshot)}}

