def bo_snapshot_at(store, build_id, revision, attempt=None):
    """Exact committed frame; a missing revision is a gap, never nearest/final fallback."""
    frames = [f for f in store.history() if f["revision"] == revision]
    if len(frames) != 1:
        raise ValueError("authoritative revision unavailable: " + str(revision))
    machine = bo_machine(store, build_id, frames[0]["snapshot"], revision)
    authority = bo_authority(machine, attempt)
    machine["current"] = authority["state"]
    return {"machine": machine, "authority": authority}

