def bo_runtime_frames(store, build_id, events):
    """Bind captured events only to their original committed transaction snapshots."""
    history = {f["revision"]: f["snapshot"] for f in store.history()}
    frames = []
    for event in events:
        revision = event["revision"]
        if revision not in history or event["build_id"] != build_id:
            continue
        machine = bo_machine(store, build_id, history[revision], revision)
        authority = bo_authority(machine, event["attempt"])
        machine["current"] = authority["state"]
        frames.append({"event_id": event["id"], "run_id": event["run_id"], "build_id": build_id,
                       "revision": revision, "machine": machine, "authority": authority})
    return {"schema": "stategraph-runtime-frames/v1", "frames": frames}

